const AFL_DIR: &str = "ATH/";

/// Main variants (engines): the group label the frontend splits into family / main variant / sub-variant.
const MAINS: [&str; 14] = [
    "YT Strategies · ATH · ATHC: %Swing exit",
    "YT Strategies · ATH · ATHC+% buy: %Swing exit",
    "YT Strategies · ATH · ATHC: Supertrend exit",
    "YT Strategies · ATH · ATHC: Other exits",
    "YT Strategies · ATH · After consecutive losses",
    "YT Strategies · ATH · Bull / Bear market",
    "YT Strategies · ATH · Delay entry",
    "YT Strategies · ATH · No-January trade",
    "YT Strategies · ATH · Ranking & stock selection",
    "YT Strategies · ATH · Reshuffling",
    "YT Strategies · ATH · Intraday & next-day (BTST)",
    "YT Strategies · ATH · Long-term highs",
    "YT Strategies · ATH · Short & combos",
    "YT Strategies · ATH · Scanners & tools",
];

/// One sub-variant: id, label, main variant (index into MAINS), the AFL it reads (relative to `ATH/`), the exact rule in words
/// (`note`), the rule lines of the Rules panel and the index of its parameter set.
struct Variant {
    id: &'static str,
    label: &'static str,
    main: usize,
    afl: &'static str,
    note: &'static str,
    rules: &'static [&'static str],
    pset: usize,
}

/// key, label, default, min, max, step
type P = (&'static str, &'static str, f64, f64, f64, f64);

