fn variant(id: &str) -> Option<&'static Variant> {
    VARIANTS.iter().find(|v| v.id == id)
}

/// True for every sub-variant id of this family.
pub fn is_variant(id: &str) -> bool {
    variant(id).is_some()
}

pub fn catalogue() -> Vec<StrategyDef> {
    VARIANTS
        .iter()
        .map(|v| StrategyDef {
            id: v.id,
            name: v.label,
            group: MAINS[v.main],
            session: 0,
            dir: "Long",
            status: Status::NotTestable(if crate::ath_run::ids().contains(&v.id) { RUNS_ON_UNIVERSE } else { NEEDS_DB }),
            needs_volume: false,
            needs_vix: false,
            needs_series: &[],
            book: BOOK,
            rules: v.rules,
            notes: v.note,
            claim: None,
        })
        .collect()
}

/// Portfolio parameters of a stock-universe run (the AFL's sizing block: Initial Equity, MAXIMUM POSITION, POS. SIZE,
/// EQUITY ALLOCATION, FIXED EQUITY / % OF Equity; BROKERAGE is the Vault's fee setting).
pub fn universe_params() -> Vec<ParamDef> {
    let p = |key, label, def, min, max, step| ParamDef { key, label, def, min, max, step };
    vec![
        p("max_positions", "Maximum open positions (AFL MAXIMUM POSITION)", 20.0, 1.0, 500.0, 1.0),
        p("pct", "Position size % of equity (0 = 100 / max positions)", 0.0, 0.0, 100.0, 0.5),
        p("sizing", "Position sizing (1 % of equity, compounding; 2 fixed amount per position, no compounding)", 1.0, 1.0, 2.0, 1.0),
        p("alloc", "Amount per position in Rs for sizing 2 (AFL EQUITY ALLOCATION; 0 = equity / max positions)", 0.0, 0.0, 100_000_000.0, 1000.0),
        p("equity", "Initial capital in Rs (AFL Initial Equity)", 1_000_000.0, 1000.0, 1_000_000_000.0, 1000.0),
    ]
}

pub fn params(id: &str) -> Option<Vec<ParamDef>> {
    let v = variant(id)?;
    let mut out: Vec<ParamDef> = PSETS[v.pset].iter().map(|&(key, label, def, min, max, step)| ParamDef { key, label, def, min, max, step }).collect();
    out.extend(universe_params());
    Some(out)
}

/// No signal / backtest code in this phase.
pub fn run(_id: &str, _x: &Ctx, _from: usize, _to: usize, _p: &Params) -> Option<Vec<Trade>> {
    None
}

pub fn family_of(id: &str) -> Option<(&'static str, &'static str, &'static str)> {
    variant(id).map(|v| ("ytath", "ATH", v.label))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;

    /// Every `{key...}` placeholder and `?key<op>n|` guard of a rule line.
    fn keys_of(line: &str) -> Vec<String> {
        let mut out = Vec::new();
        let body = line.split_once('|').map_or(line, |x| x.1);
        if let Some(g) = body.strip_prefix('?') {
            if let Some((cond, _)) = g.split_once('|') {
                out.push(cond.chars().take_while(|c| c.is_ascii_alphanumeric() || *c == '_').collect());
            }
        }
        let mut rest = line;
        while let Some(i) = rest.find('{') {
            let j = rest[i..].find('}').map_or(rest.len(), |j| i + j);
            out.push(rest[i + 1..j].split(':').next().unwrap_or("").to_string());
            rest = &rest[j.min(rest.len())..];
        }
        out
    }

    #[test]
    fn catalogue_has_every_sub_variant_in_its_group() {
        let all = catalogue();
        assert_eq!(all.len(), VARIANTS.len());
        let ids: BTreeSet<_> = all.iter().map(|d| d.id).collect();
        assert_eq!(ids.len(), all.len(), "ids are unique");
        for d in &all {
            assert!(d.id.starts_with("ytath_") && d.id.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_'), "{}", d.id);
            assert_eq!(d.group.split(" · ").count(), 3, "{}: YT Strategies · ATH · <main variant>", d.id);
            assert!(d.group.starts_with("YT Strategies · ATH · "));
            assert_eq!(d.book, BOOK);
            assert!(matches!(d.status, Status::NotTestable(_)), "{} waits for the database", d.id);
            assert!(!d.notes.is_empty(), "{}", d.id);
            assert!(family_of(d.id).is_some());
        }
        assert!(is_variant(ID));
        assert!(!is_variant("ytbtst_core"));
        for m in MAINS.iter() { assert!(all.iter().any(|d| d.group == *m), "main variant {m} has no sub-variant"); }
    }

    #[test]
    fn every_rule_placeholder_is_a_parameter() {
        for v in VARIANTS.iter() {
            let keys: BTreeSet<&str> = params(v.id).unwrap().iter().map(|p| p.key).collect();
            for line in v.rules {
                assert!(matches!(line.as_bytes().first(), Some(b'F' | b'E' | b'X')) && line.as_bytes().get(1) == Some(&b'|'), "{}: {line}", v.id);
                for k in keys_of(line) { assert!(keys.contains(k.as_str()), "{}: rule uses unknown key {k}: {line}", v.id); }
            }
        }
    }

    #[test]
    fn parameters_are_unique_and_inside_their_range() {
        for v in VARIANTS.iter() {
            let ps = params(v.id).unwrap();
            let keys: BTreeSet<&str> = ps.iter().map(|p| p.key).collect();
            assert_eq!(keys.len(), ps.len(), "{}: duplicate parameter key", v.id);
            for p in &ps {
                assert!(p.min <= p.max && p.step > 0.0, "{} {}", v.id, p.key);
            }
        }
        assert!(params("ytath_unknown").is_none());
    }
}
